WITH params AS (SELECT $1::text subject,$3::uuid version,$6::timestamptz at), captured AS MATERIALIZED(__SOURCE__), people AS MATERIALIZED(SELECT c.id,(u.id IS NOT NULL AND (c.id=$4 OR COALESCE(p.audience,'system')='system' OR p.audience='orgs' AND EXISTS(SELECT 1 FROM org_members m WHERE m.user_id=c.id AND m.org_id=ANY($5)))) visible FROM captured c LEFT JOIN users u ON u.id=c.id LEFT JOIN user_profiles p ON p.user_id=c.id WHERE c.id IS NOT NULL), page AS (SELECT id FROM people WHERE visible AND ($7::uuid IS NULL OR id>$7) ORDER BY id LIMIT $8) SELECT jsonb_build_object('ids',COALESCE((SELECT jsonb_agg(id ORDER BY id) FROM page),'[]'::jsonb),'hidden',(SELECT count(*) FROM people WHERE NOT visible))
